if (this.remoteAuthority && this.auth)
  throw new Error("remote manager-service authority cannot be combined with local space signing trust - choose one authority path, never a fallback");

const brokerRaw = await store.get(BROKER_AUTH_KEY);
const accountRaw = await store.get(spaceAccountKey(space));
if (brokerRaw !== undefined || accountRaw !== undefined) return { present: true };

let doc: { space?: unknown };
try {
  doc = JSON.parse(legacyRaw) as { space?: unknown };
